{
 "command": "cat scripts/build_search_index.py | head -50 && python scripts/build_search_index.py"
}

{
 "command": "ls var/cache/search && head -c 300 var/cache/search/shard-000.json; git status --short --ignored | head"
}

{
 "command": "python scripts/build_search_index.py --clear-cache"
}

